mapper.select:
select count(1)
from trading.demand_response
where demand_id = #{demandId}
  and responder_id = #{responderId}
  and status in ('PENDING', 'ACCEPTED')

mapper.update:
update trading.demand_response
set status = #{status},
    reject_reason = #{rejectReason},
    updated_at = #{updatedAt}
where id = #{id}

update trading.demand_response
set status = 'REJECTED',
    reject_reason = #{rejectReason},
    updated_at = #{updatedAt}
where demand_id = #{demandId}
  and id != #{excludeId}
  and status = 'PENDING'
